import type { Book, BookStatus } from '../../types';

export const STATUS_LABELS: Record<BookStatus, string> = {
  reading: 'Reading',
  read: 'Read',
  'want-to-read': 'Want to read',
  dnf: 'Did not finish',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: BookStatus): string {
  if (status === 'reading') return 'status-reading';
  if (status === 'read') return 'status-read';
  if (status === 'want-to-read') return 'status-want-to-read';
  return 'status-dnf';
}

type StatusListProps = {
  items: Book[] | null;
};

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    const skeletons = Array.from({ length: SKELETON_COUNT }, (_, i) => i);
    return (
      <ul aria-busy="true">
        {skeletons.map((i) => (
          <li key={i} className="skeleton-card" />
        ))}
      </ul>
    );
  }

  const grouped = (Object.keys(STATUS_LABELS) as BookStatus[]).reduce<
    Record<BookStatus, Book[]>
  >(
    (acc, status) => {
      acc[status] = items.filter((book) => book.status === status);
      return acc;
    },
    { reading: [], read: [], 'want-to-read': [], dnf: [] },
  );

  return (
    <div>
      {(Object.keys(STATUS_LABELS) as BookStatus[]).map((status) => {
        const group = grouped[status];
        if (group.length === 0) return null;
        return (
          <section key={status}>
            <h2>{STATUS_LABELS[status]}</h2>
            <ul>
              {group.map((book) => (
                <li key={book.id} className={statusColor(book.status)}>
                  <span>{book.title}</span>
                  <span>{book.author}</span>
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

