import { useState } from 'react';

const CHIP_LABELS = ['All', 'Active', 'Archived', 'Starred'] as const;
type ChipLabel = (typeof CHIP_LABELS)[number];

const CHIP_FILTER_STYLES = `
@layer components {
  .chip-filter {
    display: flex;
    gap: var(--shelf-space-sm);
    flex-wrap: wrap;
  }

  .chip-filter-button {
    padding: var(--shelf-space-xs) var(--shelf-space-md);
    border-radius: var(--shelf-radius-full);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-default);
    background-color: var(--shelf-bgColor-raised);
    color: var(--shelf-fgColor-default);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    line-height: var(--shelf-font-size-lg);
    cursor: pointer;
    transition:
      background-color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter),
      color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter),
      border-color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .chip-filter-button:hover {
    background-color: var(--shelf-bgColor-default);
  }

  .chip-filter-button:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .chip-filter-button:active {
    background-color: var(--shelf-bgColor-accent-active);
    color: var(--shelf-fgColor-on-accent);
    border-color: var(--shelf-bgColor-accent-active);
  }

  .chip-filter-button[aria-pressed="true"] {
    background-color: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
    border-color: var(--shelf-bgColor-accent);
  }

  .chip-filter-button[aria-pressed="true"]:hover {
    background-color: var(--shelf-bgColor-accent-hover);
    border-color: var(--shelf-bgColor-accent-hover);
  }
}
`;

type ChipFilterProps = {
  onFilterChange?: (filter: ChipLabel) => void;
};

// Owns only visual pressed state; grid filtering is wired by the consumer.
export function ChipFilter({ onFilterChange }: ChipFilterProps): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  function handleClick(label: ChipLabel): void {
    setActive(label);
    onFilterChange?.(label);
  }

  return (
    <>
      <style>{CHIP_FILTER_STYLES}</style>
      <div className="chip-filter" role="group" aria-label="Filter books">
        {CHIP_LABELS.map((label) => (
          <button
            key={label}
            className="chip-filter-button"
            aria-pressed={active === label}
            onClick={() => handleClick(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}

