import { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';

const SKELETON_COUNT = 4;

function TaskBoardHeader({ tasks }: { tasks: Task[] | null }): JSX.Element {
  const badgeText = tasks === null ? '…' : String(tasks.length);
  return (
    <header className="task-board-header">
      <h1 className="task-board-heading">Tasks</h1>
      <span className="task-board-count-badge" aria-label={`${badgeText} tasks`}>
        {badgeText}
      </span>
    </header>
  );
}

function TaskItem({ task }: { task: Task }): JSX.Element {
  return (
    <li className="task-board-item">
      <span className="task-board-item-title">{task.title}</span>
      {task.description !== undefined && (
        <span className="task-board-item-description">{task.description}</span>
      )}
    </li>
  );
}

function TaskSkeleton(): JSX.Element {
  return (
    <li className="task-board-item task-board-item-skeleton" aria-busy="true">
      <span className="task-board-skeleton-title" />
    </li>
  );
}

function TaskList({ tasks }: { tasks: Task[] | null }): JSX.Element {
  if (tasks === null) {
    return (
      <ul className="task-board-list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <TaskSkeleton key={i} />
        ))}
      </ul>
    );
  }

  if (tasks.length === 0) {
    return (
      <div className="task-board-empty" role="status">
        No tasks yet.
      </div>
    );
  }

  return (
    <ul className="task-board-list">
      {tasks.map((task) => (
        <TaskItem key={task.id} task={task} />
      ))}
    </ul>
  );
}

export function TaskBoard(): JSX.Element {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  return (
    <section className="task-board">
      <TaskBoardHeader tasks={tasks} />
      <div className="task-board-filter-bar" />
      <TaskList tasks={tasks} />
    </section>
  );
}

