import type { ReactElement } from 'react';

type PriceDisplayProps = {
  price: number;
  originalPrice?: number;
};

function formatPrice(value: number): string {
  // Math.ceil avoids under-charging when fractional cents round down
  const cents = Math.ceil(value * 100);
  return (cents / 100).toFixed(2);
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): ReactElement {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current">${formatPrice(price)}</span>
      {hasDiscount && (
        <s className="price-display-original">${formatPrice(originalPrice)}</s>
      )}
    </span>
  );
}
